#include <bits/stdc++.h>
using namespace std;

const long long MOD_A = 1000000007;
const long long MOD_B = 998244353;
const int MAX_DEPTH = 7;
const long long MULT = 1000000;

long long limit_value, order_count;
int total_res;
int prefix_sum_arr[MAX_DEPTH];
vector<int> digit_vectors[MAX_DEPTH];

void generate(int start, int depth) {
    order_count++;
    digit_vectors[depth].push_back(((order_count - start) % MOD_B + MOD_B) % MOD_B);
    prefix_sum_arr[depth] = (prefix_sum_arr[depth] + digit_vectors[depth].back()) % MOD_A;
    if (depth == 6) return;
    for (int d = 0; d <= 9; d++) {
        generate(start * 10 + d, depth + 1);
    }
}

void process(long long x) {
    if (x > limit_value) return;
    if (x * MULT + MULT - 1 <= limit_value && x * MULT * 10 > limit_value) {
        long long saved_order = order_count;
        for (int depth = 0, factor = 1; depth <= 6; depth++, factor *= 10) {
            int size = (int)digit_vectors[depth].size();
            int diff = (int)(((saved_order - x * factor) % MOD_B + MOD_B) % MOD_B);
            int pos = (int)(lower_bound(digit_vectors[depth].begin(), digit_vectors[depth].end(), (int)(MOD_B - diff)) - digit_vectors[depth].begin());
            total_res = (total_res + 1LL * diff * size + prefix_sum_arr[depth]) % MOD_A;
            total_res = (total_res - 1LL * MOD_B * (size - pos) % MOD_A + MOD_A) % MOD_A;
            order_count += size;
        }
        return;
    }
    order_count++;
    total_res = (total_res + ((order_count - x) % MOD_B + MOD_B) % MOD_B) % MOD_A;
    for (int d = 0; d <= 9; d++) {
        process(x * 10 + d);
    }
}

int main() {
    cin >> limit_value;
    order_count = 0;
    generate(0, 0);
    for (int i = 0; i <= 6; i++) {
        sort(digit_vectors[i].begin(), digit_vectors[i].end());
    }
    order_count = 0;
    for (int i = 1; i <= 9; i++) {
        process(i);
    }
    cout << total_res << "\n";
    return 0;
}
